        // eslint-disable-next-line @typescript-eslint/ban-ts-comment
        //@ts-ignore
        const { businessID, sub: subject } = request.user;
        return this.measurementConfigService.create({ ...createMeasurementConfigDto, businessID }, subject);
    }

