export enum SupportedDatastores {
    s3 = 's3',
}

/**
 * The default region used for datastore based measurements when none is provided.
 */
export const DEFAULT_DATASTORE_REGION = 'us-east-1';

/**
 * Optional context needed to identify the resources belonging to a datastore based measurement.
 * The information can either live on the {@link DatastoreAccessInformation} itself,
 * or be handed over by the caller (ie. the measurement configuration orchestration).
 */
export interface DatastoreAccessContext {
    businessID?: string;
    measurementId?: string;
}

/**
 *
 * This Class represents the access information and control data structure for Datastore based Measurement solutions
 * Specifically this is the access information needed for connectors inside of Confluent Cloud to pull data from a clients env.
 * There are many different connectors with different access and control needs.
 * For example a MySQL connector is not the same as a Kinesis Connector
 * */
export class DatastoreAccessInformation {
    /**
     * Underlying datastore platform which enterprise ingests usage data from. Optional, default is `s3`.
     *
     */
    @Matches(
        `^${Object.values(SupportedDatastores)
            .filter((v) => typeof v !== 'number')
            .join('|')}$`,
        'i'
    )
    @IsOptional()
    @ApiProperty({
        enum: SupportedDatastores,
        isArray: false,
        required: false,
        examples: ['s3'],
    })
    public platform?: SupportedDatastores;

    /**
     * The unique ID of the cloud account which pushes usage data into the enterprise managed datastore. Required.
     * @example "623673123435"
     */
    @IsString()
    @IsNotEmpty()
    @ApiProperty({ example: '623673123435' })
    public accountId: string;

    /**
     * The IAM role generated by enterprise which the account identified by `accountId` is allowed to assume
     * in order to write usage data into the ingestion location, and read failures from the DLQ.
     * Generated by enterprise, any provided value is ignored.
     * <br><br>
     * Example `"arn:aws:iam::647662420899:role/datastore-myBusiness-de388932-a7e1-11ed-afa1-0242ac120002"`
     */
    @IsString()
    @IsOptional()
    @ApiProperty({ required: false })
    public iamRoleArn?: string;

    /**
     * The external ID which must be provided when assuming the generated `iamRoleArn`.
     * Generated by enterprise, any provided value is ignored.
     */
    @IsString()
    @IsOptional()
    @ApiProperty({ required: false })
    public externalId?: string;

    /**
     * The location usage data records must be written to. Generated by enterprise.
     * <br><br>
     * Example `"s3://enterprise-usage-record-dump-bucket/myBusiness/"`
     */
    @IsString()
    @IsOptional()
    @ApiProperty({ required: false })
    public ingestion?: string;

    /**
     * The location where records that could not be processed are written to. Generated by enterprise.
     * <br><br>
     * Example `"s3://enterprise-usage-record-dlq-bucket/myBusiness/"`
     */
    @IsString()
    @IsOptional()
    @ApiProperty({ required: false })
    public dlq?: string;

    /**
     * The region the ingestion and DLQ locations live in. Optional, default is `us-east-1`.
     * @example "us-east-1"
     */
    @IsString()
    @IsOptional()
    @ApiProperty({ required: false, example: DEFAULT_DATASTORE_REGION })
    public region?: string;

    @ApiHideProperty()
    @IsString()
    @IsOptional()
    public businessID?: string;

    @ApiHideProperty()
    @IsString()
    @IsOptional()
    public measurementId?: string;

    constructor(datastoreAccessInformation: DatastoreAccessInformation) {
        if (datastoreAccessInformation) {
            const {
                platform,
                accountId,
                iamRoleArn,
                externalId,
                ingestion,
                dlq,
                region,
                businessID,
                measurementId,
                // Legacy field names are still accepted as input
                // eslint-disable-next-line @typescript-eslint/ban-ts-comment
                // @ts-ignore
                datastoreType,
                // eslint-disable-next-line @typescript-eslint/ban-ts-comment
                // @ts-ignore
                cloudId,
            } = datastoreAccessInformation;

            this.platform = (platform ? platform : datastoreType ? datastoreType : SupportedDatastores.s3) as
                | SupportedDatastores
                | undefined;
            this.accountId = accountId ? accountId : cloudId;
            this.iamRoleArn = iamRoleArn ? iamRoleArn : undefined;
            this.externalId = externalId ? externalId : undefined;
            this.ingestion = ingestion ? ingestion : undefined;
            this.dlq = dlq ? dlq : undefined;
            this.region = region ? region : DEFAULT_DATASTORE_REGION;
            this.businessID = businessID;
            this.measurementId = measurementId;
        }
    }

    public static transformer(datastoreAccessInformation: DatastoreAccessInformation, influxPoint: Point) {
        if (datastoreAccessInformation) {
            const { platform, accountId, iamRoleArn, externalId, ingestion, dlq, region } =
                datastoreAccessInformation;
            if (platform) influxPoint.tag('platform', platform);
            if (accountId) influxPoint.tag('accountId', accountId);
            if (iamRoleArn) influxPoint.tag('iamRoleArn', iamRoleArn);
            if (externalId) influxPoint.tag('externalId', externalId);
            if (ingestion) influxPoint.tag('ingestion', ingestion);
            if (dlq) influxPoint.tag('dlq', dlq);
            if (region) influxPoint.tag('region', region);
        }
        return influxPoint;
    }

    public static dbModelToEntity({
        platform,
        accountId,
        iamRoleArn,
        externalId,
        ingestion,
        dlq,
        region,
        businessID,
        measurementId,
        // Support measurements created before the datastore access information was reshaped
        datastoreType,
        cloudId,
    }: {
        [x: string]: any;
    }) {
        return new DatastoreAccessInformation({
            platform: platform ? platform.toLowerCase() : datastoreType,
            accountId: accountId ? accountId : cloudId,
            iamRoleArn,
            externalId,
            ingestion,
            dlq,
            region,
            businessID,
            measurementId,
        });
    }

    /**
     * The unique name of the IAM role, and of the IAM policy, backing a datastore based measurement.
     */
    public static roleName({ businessID, measurementId }: DatastoreAccessContext) {
        return `datastore-${businessID}-${measurementId}`;
    }

    public static policyName(context: DatastoreAccessContext) {
        return `${DatastoreAccessInformation.roleName(context)}-policy`;
    }

    /**
     * The location, inside of the enterprise managed buckets, dedicated to a single business.
     */
    public static locations(businessID: string) {
        const ingestionBucket = `${process.env.DB_MEASUREMENT_BUCKET_NAME}`;
        const dlqBucket = `${process.env.DB_MEASUREMENT_DLQ_BUCKET_NAME}`;
        return {
            ingestionBucket,
            dlqBucket,
            prefix: `${businessID}/`,
            ingestion: `s3://${ingestionBucket}/${businessID}/`,
            dlq: `s3://${dlqBucket}/${businessID}/`,
        };
    }

    /**
     * The trust policy of the generated role.
     * Only the customer account, presenting the generated external ID, is allowed to assume the role.
     */
    public static assumeRolePolicyDocument({ accountId, externalId }: DatastoreAccessInformation) {
        return {
            Version: '2012-10-17',
            Statement: [
                {
                    Sid: 'EnterpriseDatastoreMeasurementTrust',
                    Effect: 'Allow',
                    Principal: {
                        AWS: `arn:aws:iam::${accountId}:root`,
                    },
                    Action: 'sts:AssumeRole',
                    Condition: {
                        StringEquals: {
                            'sts:ExternalId': externalId,
                        },
                    },
                },
            ],
        };
    }

    /**
     * The permissions of the generated role, strictly scoped to the prefixes owned by a single business.
     */
    public static accessPolicyDocument(businessID: string) {
        const { ingestionBucket, dlqBucket, prefix } = DatastoreAccessInformation.locations(businessID);
        return {
            Version: '2012-10-17',
            Statement: [
                {
                    Sid: 'EnterpriseDatastoreMeasurementIngestion',
                    Effect: 'Allow',
                    Action: ['s3:PutObject', 's3:GetObject', 's3:AbortMultipartUpload', 's3:ListMultipartUploadParts'],
                    Resource: [`arn:aws:s3:::${ingestionBucket}/${prefix}*`],
                },
                {
                    Sid: 'EnterpriseDatastoreMeasurementDLQ',
                    Effect: 'Allow',
                    Action: ['s3:GetObject'],
                    Resource: [`arn:aws:s3:::${dlqBucket}/${prefix}*`],
                },
                {
                    Sid: 'EnterpriseDatastoreMeasurementList',
                    Effect: 'Allow',
                    Action: ['s3:ListBucket'],
                    Resource: [`arn:aws:s3:::${ingestionBucket}`, `arn:aws:s3:::${dlqBucket}`],
                    Condition: {
                        StringLike: {
                            's3:prefix': [`${prefix}*`],
                        },
                    },
                },
            ],
        };
    }

    private static resolveContext(
        dbAccessInformation: DatastoreAccessInformation,
        context?: DatastoreAccessContext | string,
        measurementId?: string
    ): DatastoreAccessContext {
        if (typeof context === 'string') {
            return {
                businessID: context,
                measurementId: measurementId ? measurementId : dbAccessInformation?.measurementId,
            };
        }
        return {
            businessID: context?.businessID ? context.businessID : dbAccessInformation?.businessID,
            measurementId: context?.measurementId ? context.measurementId : dbAccessInformation?.measurementId,
        };
    }

    private static client() {
        return new IAM({ region: process.env.AWS_REGION ? process.env.AWS_REGION : DEFAULT_DATASTORE_REGION });
    }

    private static handleError(error, accountId: string) {
        if (error?.name === 'MalformedPolicyDocument' || error?.Code === 'MalformedPolicy') {
            throw new BadRequestException(`AccountId: ${accountId} is invalid`);
        }
        throw error;
    }

    /**
     * Provisions the access needed for a customer to push usage data into the enterprise managed datastore.
     *
     * A uniquely named IAM role, trusting the customer account with a freshly generated external ID,
     * is created alongside an inline policy scoped to the ingestion and DLQ prefixes of the business.
     * The generated values are set on the access information so they get returned and persisted.
     */
    public static async setupAccess(
        dbAccessInformation: DatastoreAccessInformation,
        context?: DatastoreAccessContext | string,
        measurementIdArgument?: string
    ): Promise<DatastoreAccessInformation> {
        if (!dbAccessInformation) {
            return dbAccessInformation;
        }
        const { platform, accountId } = dbAccessInformation;
        if (platform && platform.toLowerCase() !== SupportedDatastores.s3) {
            return dbAccessInformation;
        }
        const { businessID, measurementId } = DatastoreAccessInformation.resolveContext(
            dbAccessInformation,
            context,
            measurementIdArgument
        );
        const roleName = DatastoreAccessInformation.roleName({ businessID, measurementId });
        const { ingestion, dlq } = DatastoreAccessInformation.locations(businessID);

        dbAccessInformation.platform = platform ? platform : SupportedDatastores.s3;
        dbAccessInformation.externalId = randomUUID();
        dbAccessInformation.ingestion = ingestion;
        dbAccessInformation.dlq = dlq;
        dbAccessInformation.region = dbAccessInformation.region
            ? dbAccessInformation.region
            : DEFAULT_DATASTORE_REGION;

        const iam = DatastoreAccessInformation.client();
        try {
            const { Role } = await iam.createRole({
                RoleName: roleName,
                AssumeRolePolicyDocument: JSON.stringify(
                    DatastoreAccessInformation.assumeRolePolicyDocument(dbAccessInformation)
                ),
                Description: `Datastore based measurement access for businessID: ${businessID} measurementId: ${measurementId}`,
                Tags: [
                    { Key: 'businessID', Value: `${businessID}` },
                    { Key: 'measurementId', Value: `${measurementId}` },
                ],
            });
            await iam.putRolePolicy({
                RoleName: roleName,
                PolicyName: DatastoreAccessInformation.policyName({ businessID, measurementId }),
                PolicyDocument: JSON.stringify(DatastoreAccessInformation.accessPolicyDocument(businessID)),
            });
            dbAccessInformation.iamRoleArn = Role?.Arn
                ? Role.Arn
                : `arn:aws:iam::${process.env.AWS_ACCOUNT_ID ? process.env.AWS_ACCOUNT_ID : ''}:role/${roleName}`;
        } catch (e) {
            DatastoreAccessInformation.handleError(e, accountId);
        }
        return dbAccessInformation;
    }

    /**
     * Updates the trust of an already provisioned role so a new customer account can assume it.
     * The generated role and external ID are preserved.
     */
    public static async updateAccess(
        dbAccessInformation: DatastoreAccessInformation,
        context?: DatastoreAccessContext | string,
        measurementIdArgument?: string
    ): Promise<DatastoreAccessInformation> {
        if (!dbAccessInformation) {
            return dbAccessInformation;
        }
        const { platform, accountId } = dbAccessInformation;
        if (platform && platform.toLowerCase() !== SupportedDatastores.s3) {
            return dbAccessInformation;
        }
        const { businessID, measurementId } = DatastoreAccessInformation.resolveContext(
            dbAccessInformation,
            context,
            measurementIdArgument
        );
        const roleName = DatastoreAccessInformation.roleName({ businessID, measurementId });
        const { ingestion, dlq } = DatastoreAccessInformation.locations(businessID);

        // The role and its external ID are never regenerated on an update
        dbAccessInformation.platform = platform ? platform : SupportedDatastores.s3;
        dbAccessInformation.externalId = dbAccessInformation.externalId ? dbAccessInformation.externalId : randomUUID();
        dbAccessInformation.ingestion = dbAccessInformation.ingestion ? dbAccessInformation.ingestion : ingestion;
        dbAccessInformation.dlq = dbAccessInformation.dlq ? dbAccessInformation.dlq : dlq;
        dbAccessInformation.region = dbAccessInformation.region
            ? dbAccessInformation.region
            : DEFAULT_DATASTORE_REGION;
        dbAccessInformation.iamRoleArn = dbAccessInformation.iamRoleArn
            ? dbAccessInformation.iamRoleArn
            : `arn:aws:iam::${process.env.AWS_ACCOUNT_ID ? process.env.AWS_ACCOUNT_ID : ''}:role/${roleName}`;

        const iam = DatastoreAccessInformation.client();
        try {
            await iam.updateAssumeRolePolicy({
                RoleName: roleName,
                PolicyDocument: JSON.stringify(
                    DatastoreAccessInformation.assumeRolePolicyDocument(dbAccessInformation)
                ),
            });
        } catch (e) {
            DatastoreAccessInformation.handleError(e, accountId);
        }
        return dbAccessInformation;
    }
}

