import { MeasurementFormat } from './measurement.interface';

const eventEmitter = new EventEmitter();

/**
 * The default region used when no region is configured for the enterprise managed buckets.
 */
const DEFAULT_REGION = 'us-east-1';

/**
 * The suffix appended to the mirrored source key of a failed record inside of the DLQ.
 */
export const DLQ_KEY_SUFFIX = '.message.text';

/**
 * A failure which could not be turned into a usage record and therefore has to be
 * handed over to the dead letter queue for manual processing.
 */
export interface PublishFailureToDLQRequest {
    /**
     * The input which failed to be processed.
     */
    input?: unknown;
    /**
     * Alias of `input`, the raw message which failed to be processed.
     */
    message?: unknown;
    /**
     * The key of the object the failed input originated from.
     * Both absolute (`s3://bucket/key`) and relative (`key`) keys are supported.
     */
    s3Key?: string;
    /**
     * Alias of `s3Key`.
     */
    sourceKey?: string;
    /**
     * The bucket the failure gets written to. Defaults to `DB_MEASUREMENT_DLQ_BUCKET_NAME`.
     */
    bucket?: string;
    /**
     * The error which caused the failure.
     */
    error?: unknown;
    /**
     * Any additional information which helps processing the failure manually.
     */
    metadata?: Record<string, unknown>;
    /**
     * The component which failed to process the input.
     */
    source?: string;
}

