    static awsTagKeyReducer(Tags: Tag[]) {
        if (Tags) {
            return Tags.reduce((acc, { Key, Value }): any => {
                if (StandardMeasurementEntity.allowedTags.includes(Key)) {
                    acc[Key] = Value;
                }
                return acc;
            }, {});
        } else {
            return {};
        }
    }

    /**
     * Turns any source key into a key relative to its bucket.
     * Keys which already are relative are returned untouched.
     */
    static relativeSourceKey(sourceKey: string): string {
        if (!sourceKey) {
            return '';
        }
        return `${sourceKey}`
            .replace(/^[a-zA-Z0-9]+:\/\/[^/]+\/?/, '')
            .replace(/^\/+/, '')
            .trim();
    }

    /**
     * Derives the businessID owning a source key. The first segment of a key is always the businessID.
     */
    static businessIDFromSourceKey(sourceKey: string): string {
        const [businessID] = StandardMeasurementEntity.relativeSourceKey(sourceKey).split('/');
        return businessID;
    }

    /**
     * Writes an input which could not be processed into the configured dead letter queue.
     *
     * The failure is mirrored under the key of the object it originated from, suffixed with
     * `.message.text`, and holds both the failed input and the metadata of the failed processing.
     */
    static async publishFailureToDLQ(
        failure: PublishFailureToDLQRequest | unknown,
        sourceKeyArgument?: string
    ): Promise<{ message: string; bucket: string; key: string }> {
        const request: PublishFailureToDLQRequest =
            failure && typeof failure === 'object' && sourceKeyArgument === undefined
                ? (failure as PublishFailureToDLQRequest)
                : { input: failure, sourceKey: sourceKeyArgument };

        const input = request.input !== undefined ? request.input : request.message !== undefined ? request.message : request;
        const sourceKey = request.s3Key ? request.s3Key : request.sourceKey;
        const bucket = request.bucket ? request.bucket : `${process.env.DB_MEASUREMENT_DLQ_BUCKET_NAME}`;
        const relativeSourceKey = StandardMeasurementEntity.relativeSourceKey(sourceKey);
        const key = relativeSourceKey
            ? `${relativeSourceKey}${DLQ_KEY_SUFFIX}`
            : `${StandardMeasurementEntity.businessIDFromSourceKey(sourceKey)
                  ? StandardMeasurementEntity.businessIDFromSourceKey(sourceKey)
                  : 'unknown'}/${randomUUID()}${DLQ_KEY_SUFFIX}`;
        const error = request.error;
        const body = {
            failedInput: input,
            processingMetadata: {
                error: error instanceof Error ? error.message : error,
                source: request.source,
                sourceKey: relativeSourceKey ? relativeSourceKey : sourceKey,
                originalSourceKey: sourceKey,
                sourceBucket: `${process.env.DB_MEASUREMENT_BUCKET_NAME}`,
                dlqBucket: bucket,
                dlqKey: key,
                businessID: StandardMeasurementEntity.businessIDFromSourceKey(sourceKey),
                failedAt: new Date().toISOString(),
                ...request.metadata,
            },
        };

        StandardMeasurementEntity.logger.error(`Publishing failed record to DLQ: s3://${bucket}/${key}`);

        const s3 = new S3({ region: process.env.AWS_REGION ? process.env.AWS_REGION : DEFAULT_REGION });
        await s3.putObject({
            Bucket: bucket,
            Key: key,
            Body: JSON.stringify(body),
            ContentType: 'text/plain',
        });

        AuditService.publishEvent({
            data: [body],
            message: 'Published failed record to DLQ',
            topic: AuditScope.ERROR,
        });

        return { message: 'Published failure to DLQ', bucket, key };
    }
}

