import { Injectable } from '@nestjs/common';
import { AuditScope, AuditProcessor, AuditPublishRequest } from './entities/audit.interface';
import { AuditEntity, ErrorAuditProcessor } from './entities/audit.entity';

@Injectable()
export class AuditService {
    private static auditSystem = new AuditEntity();

    public subscribeForAuditEvents() {
        AuditService.auditSystem.subscribe(AuditScope.ERROR, new ErrorAuditProcessor());
    }

    public static publishEvent(auditPublishRequest: AuditPublishRequest) {
        AuditService.auditSystem.publish(auditPublishRequest);
    }
}

export type AuditPublishResponse = {
    message: string;
    id: string;
    data: Array<any>;
};

export enum AuditScope {
    ERROR = 'ERROR',
}

export type AuditPublishRequest = {
    message: string;
    topic: AuditScope;
    data: Array<any>;
};
export interface AuditProcessor {
    process: (auditPublishRequest: AuditPublishRequest) => void;
}

export interface Audit {
    publish: (publishRequest: AuditPublishRequest) => AuditPublishResponse;
    subscribe: (auditLevel: AuditScope, processor: AuditProcessor) => void;
}
import { randomUUID } from 'crypto';
import { Audit, AuditScope, AuditProcessor, AuditPublishRequest, AuditPublishResponse } from './audit.interface';
import EventEmitter from 'events';
import { Logger } from '@nestjs/common';

export class AuditEntity implements Audit {
    private eventEmitter: EventEmitter;

    constructor() {
        this.eventEmitter = new EventEmitter();
    }

    publish(publishRequest: AuditPublishRequest): AuditPublishResponse {
        this.eventEmitter.emit(publishRequest.topic, publishRequest);
        return {
            message: 'Audit published',
            id: randomUUID(),
            data: [publishRequest],
        };
    }
    subscribe(auditLevel: AuditScope, processor: AuditProcessor) {
        this.eventEmitter.on(auditLevel, processor.process);
    }
}

export class ErrorAuditProcessor implements AuditProcessor {
    private static readonly logger = new Logger(ErrorAuditProcessor.name);
    async process(auditPublishRequest: AuditPublishRequest) {
        ErrorAuditProcessor.logger.error('Auditing Error Occurred');
        ErrorAuditProcessor.logger.error(auditPublishRequest.message);
        ErrorAuditProcessor.logger.error(JSON.stringify(auditPublishRequest.data));
    }
}

