import { IAM, CreateRoleCommand, PutRolePolicyCommand, UpdateAssumeRolePolicyCommand } from '@aws-sdk/client-iam';
import { mockClient } from 'aws-sdk-client-mock';
import { measurementMode } from '../dto/create-measurement-config.dto';
import {
    DatastoreAccessInformation,
    MeasurementConfigEntity,
    SupportedDatastores,
} from './measurement-config.entity';

const iamMock = mockClient(IAM);

describe('DatastoreAccessInformation', () => {
    const businessID = 'fakeBusiness';
    const measurementId = 'fake-measurement-id';
    const accountId = '623673123435';
    const roleName = `datastore-${businessID}-${measurementId}`;

    beforeEach(() => {
        iamMock.reset();
        process.env.DB_MEASUREMENT_BUCKET_NAME = 'enterprise-usage-record-dump-bucket';
        process.env.DB_MEASUREMENT_DLQ_BUCKET_NAME = 'enterprise-usage-record-dlq-bucket';
        iamMock.on(CreateRoleCommand).resolves({
            Role: { Arn: `arn:aws:iam::647662420899:role/${roleName}` },
        } as never);
        iamMock.on(PutRolePolicyCommand).resolves({});
        iamMock.on(UpdateAssumeRolePolicyCommand).resolves({});
    });

    it('defaults the platform and region', () => {
        const configuration = new DatastoreAccessInformation({ accountId } as DatastoreAccessInformation);
        expect(configuration.platform).toEqual(SupportedDatastores.s3);
        expect(configuration.region).toEqual('us-east-1');
        expect(configuration.accountId).toEqual(accountId);
    });

    it('provisions a uniquely named role trusting the customer account with a fresh external id', async () => {
        const entity = new MeasurementConfigEntity({
            measurementId,
            businessID,
            measurementMode: measurementMode.datastoreBased,
            measurementConfiguration: { accountId } as DatastoreAccessInformation,
            measurementName: 'fakeMeasurement',
            subject: 'fakeSubject',
        });

        const configuration = (await MeasurementConfigEntity.setupAccessIfRequired(
            entity
        )) as DatastoreAccessInformation;

        const [createRole] = iamMock.commandCalls(CreateRoleCommand);
        expect(createRole.args[0].input.RoleName).toEqual(roleName);
        const trust = JSON.parse(createRole.args[0].input.AssumeRolePolicyDocument);
        expect(trust.Statement[0].Principal.AWS).toEqual(`arn:aws:iam::${accountId}:root`);
        expect(trust.Statement[0].Condition.StringEquals['sts:ExternalId']).toEqual(configuration.externalId);

        const [putRolePolicy] = iamMock.commandCalls(PutRolePolicyCommand);
        expect(putRolePolicy.args[0].input.RoleName).toEqual(roleName);
        const policy = JSON.parse(putRolePolicy.args[0].input.PolicyDocument);
        expect(JSON.stringify(policy)).toContain(
            `arn:aws:s3:::${process.env.DB_MEASUREMENT_BUCKET_NAME}/${businessID}/*`
        );
        expect(JSON.stringify(policy)).toContain(
            `arn:aws:s3:::${process.env.DB_MEASUREMENT_DLQ_BUCKET_NAME}/${businessID}/*`
        );

        expect(configuration.iamRoleArn).toEqual(`arn:aws:iam::647662420899:role/${roleName}`);
        expect(configuration.externalId).toBeDefined();
        expect(configuration.ingestion).toContain(businessID);
        expect(configuration.dlq).toContain(businessID);
        expect(configuration.region).toEqual('us-east-1');
        expect(configuration.platform).toEqual(SupportedDatastores.s3);
    });

    it('updates the trust of the role while preserving the role and external id', async () => {
        const externalId = 'already-generated-external-id';
        const iamRoleArn = `arn:aws:iam::647662420899:role/${roleName}`;
        const updatedAccountId = '999999999999';
        const entity = new MeasurementConfigEntity({
            measurementId,
            businessID,
            measurementMode: measurementMode.datastoreBased,
            measurementConfiguration: {
                accountId: updatedAccountId,
                externalId,
                iamRoleArn,
            } as DatastoreAccessInformation,
            measurementName: 'fakeMeasurement',
            subject: 'fakeSubject',
        });

        const configuration = (await MeasurementConfigEntity.updateAccessIfRequired(
            entity
        )) as DatastoreAccessInformation;

        const [updateTrust] = iamMock.commandCalls(UpdateAssumeRolePolicyCommand);
        expect(updateTrust.args[0].input.RoleName).toEqual(roleName);
        const trust = JSON.parse(updateTrust.args[0].input.PolicyDocument);
        expect(trust.Statement[0].Principal.AWS).toEqual(`arn:aws:iam::${updatedAccountId}:root`);
        expect(trust.Statement[0].Condition.StringEquals['sts:ExternalId']).toEqual(externalId);
        expect(iamMock.commandCalls(CreateRoleCommand).length).toEqual(0);
        expect(configuration.externalId).toEqual(externalId);
        expect(configuration.iamRoleArn).toEqual(iamRoleArn);
    });

    it('does nothing for measurement modes which do not need provisioning', async () => {
        const entity = new MeasurementConfigEntity({
            measurementId,
            businessID,
            measurementMode: measurementMode.agentBased,
            measurementConfiguration: { iamRoleArn: 'fakeArn', hostingPlatform: 'k8spod' } as never,
            measurementName: 'fakeMeasurement',
            subject: 'fakeSubject',
        });
        await MeasurementConfigEntity.setupAccessIfRequired(entity);
        expect(iamMock.calls().length).toEqual(0);
    });
});

