/**
 * The IAM client used to provision the access of a datastore based measurement.
 * Both the aggregated and the command based flavour of the AWS SDK client are supported.
 */
private static client() {
    const configuration = {
        region: process.env.AWS_REGION ? process.env.AWS_REGION : DEFAULT_DATASTORE_REGION,
    };
    if (typeof IAM === 'function') {
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        const iam: any = new IAM(configuration);
        return {
            createRole: (input) =>
                typeof iam.createRole === 'function' ? iam.createRole(input) : iam.send(new CreateRoleCommand(input)),
            putRolePolicy: (input) =>
                typeof iam.putRolePolicy === 'function'
                    ? iam.putRolePolicy(input)
                    : iam.send(new PutRolePolicyCommand(input)),
            updateAssumeRolePolicy: (input) =>
                typeof iam.updateAssumeRolePolicy === 'function'
                    ? iam.updateAssumeRolePolicy(input)
                    : iam.send(new UpdateAssumeRolePolicyCommand(input)),
        };
    }
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const client: any = new IAMClient(configuration);
    return {
        createRole: (input) => client.send(new CreateRoleCommand(input)),
        putRolePolicy: (input) => client.send(new PutRolePolicyCommand(input)),
        updateAssumeRolePolicy: (input) => client.send(new UpdateAssumeRolePolicyCommand(input)),
    };
}

