/**
 * Writes an object into S3.
 * Both the aggregated and the command based flavour of the AWS SDK client are supported.
 */
private static async putObject(input) {
    const configuration = { region: process.env.AWS_REGION ? process.env.AWS_REGION : DEFAULT_REGION };
    if (typeof S3 === 'function') {
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        const s3: any = new S3(configuration);
        if (typeof s3.putObject === 'function') {
            return s3.putObject(input);
        }
        return s3.send(new PutObjectCommand(input));
    }
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const client: any = new S3Client(configuration);
    return client.send(new PutObjectCommand(input));
}

