import { measurementMode } from '../dto/create-measurement-config.dto';
import {
    DatastoreAccessInformation,
    MeasurementConfigEntity,
    SupportedDatastores,
} from './measurement-config.entity';

const mockCreateRole = jest.fn();
const mockPutRolePolicy = jest.fn();
const mockUpdateAssumeRolePolicy = jest.fn();

jest.mock('@aws-sdk/client-iam', () => ({
    IAM: jest.fn().mockImplementation(() => ({
        createRole: mockCreateRole,
        putRolePolicy: mockPutRolePolicy,
        updateAssumeRolePolicy: mockUpdateAssumeRolePolicy,
    })),
}));

describe('DatastoreAccessInformation', () => {
    const businessID = 'fakeBusiness';
    const measurementId = 'fake-measurement-id';
    const accountId = '623673123435';
    const roleName = `datastore-${businessID}-${measurementId}`;

    beforeEach(() => {
        jest.clearAllMocks();
        process.env.DB_MEASUREMENT_BUCKET_NAME = 'enterprise-usage-record-dump-bucket';
        process.env.DB_MEASUREMENT_DLQ_BUCKET_NAME = 'enterprise-usage-record-dlq-bucket';
        mockCreateRole.mockResolvedValue({ Role: { Arn: `arn:aws:iam::647662420899:role/${roleName}` } });
        mockPutRolePolicy.mockResolvedValue({});
        mockUpdateAssumeRolePolicy.mockResolvedValue({});
    });

    it('defaults the platform and region', () => {
        const configuration = new DatastoreAccessInformation({ accountId } as DatastoreAccessInformation);
        expect(configuration.platform).toEqual(SupportedDatastores.s3);
        expect(configuration.region).toEqual('us-east-1');
        expect(configuration.accountId).toEqual(accountId);
    });

    it('provisions a uniquely named role trusting the customer account with a fresh external id', async () => {
        const entity = new MeasurementConfigEntity({
            measurementId,
            businessID,
            measurementMode: measurementMode.datastoreBased,
            measurementConfiguration: { accountId } as DatastoreAccessInformation,
            measurementName: 'fakeMeasurement',
            subject: 'fakeSubject',
        });

        const configuration = (await MeasurementConfigEntity.setupAccessIfRequired(
            entity
        )) as DatastoreAccessInformation;

        const [[createRoleInput]] = mockCreateRole.mock.calls;
        expect(createRoleInput.RoleName).toEqual(roleName);
        const trust = JSON.parse(createRoleInput.AssumeRolePolicyDocument);
        expect(trust.Statement[0].Principal.AWS).toEqual(`arn:aws:iam::${accountId}:root`);
        expect(trust.Statement[0].Condition.StringEquals['sts:ExternalId']).toEqual(configuration.externalId);

        const [[putRolePolicyInput]] = mockPutRolePolicy.mock.calls;
        expect(putRolePolicyInput.RoleName).toEqual(roleName);
        expect(putRolePolicyInput.PolicyDocument).toContain(
            `arn:aws:s3:::${process.env.DB_MEASUREMENT_BUCKET_NAME}/${businessID}/*`
        );
        expect(putRolePolicyInput.PolicyDocument).toContain(
            `arn:aws:s3:::${process.env.DB_MEASUREMENT_DLQ_BUCKET_NAME}/${businessID}/*`
        );

        expect(configuration.iamRoleArn).toEqual(`arn:aws:iam::647662420899:role/${roleName}`);
        expect(configuration.externalId).toBeDefined();
        expect(configuration.ingestion).toContain(businessID);
        expect(configuration.dlq).toContain(businessID);
        expect(configuration.region).toEqual('us-east-1');
        expect(configuration.platform).toEqual(SupportedDatastores.s3);
    });

    it('updates the trust of the role while preserving the role and external id', async () => {
        const externalId = 'already-generated-external-id';
        const iamRoleArn = `arn:aws:iam::647662420899:role/${roleName}`;
        const updatedAccountId = '999999999999';
        const entity = new MeasurementConfigEntity({
            measurementId,
            businessID,
            measurementMode: measurementMode.datastoreBased,
            measurementConfiguration: {
                accountId: updatedAccountId,
                externalId,
                iamRoleArn,
            } as DatastoreAccessInformation,
            measurementName: 'fakeMeasurement',
            subject: 'fakeSubject',
        });

        const configuration = (await MeasurementConfigEntity.updateAccessIfRequired(
            entity
        )) as DatastoreAccessInformation;

        const [[updateTrustInput]] = mockUpdateAssumeRolePolicy.mock.calls;
        expect(updateTrustInput.RoleName).toEqual(roleName);
        const trust = JSON.parse(updateTrustInput.PolicyDocument);
        expect(trust.Statement[0].Principal.AWS).toEqual(`arn:aws:iam::${updatedAccountId}:root`);
        expect(trust.Statement[0].Condition.StringEquals['sts:ExternalId']).toEqual(externalId);
        expect(mockCreateRole).not.toHaveBeenCalled();
        expect(configuration.externalId).toEqual(externalId);
        expect(configuration.iamRoleArn).toEqual(iamRoleArn);
    });

    it('does nothing for measurement modes which do not need provisioning', async () => {
        const entity = new MeasurementConfigEntity({
            measurementId,
            businessID,
            measurementMode: measurementMode.agentBased,
            measurementConfiguration: { iamRoleArn: 'fakeArn', hostingPlatform: 'k8spod' } as never,
            measurementName: 'fakeMeasurement',
            subject: 'fakeSubject',
        });
        await MeasurementConfigEntity.setupAccessIfRequired(entity);
        expect(mockCreateRole).not.toHaveBeenCalled();
        expect(mockUpdateAssumeRolePolicy).not.toHaveBeenCalled();
    });
});

import { S3, PutObjectCommand } from '@aws-sdk/client-s3';
import { mockClient } from 'aws-sdk-client-mock';
import { Test, TestingModule } from '@nestjs/testing';
import { PrivateAPIUsageController } from './usage.controller';
import { UsageService } from './usage.service';

const s3Mock = mockClient(S3);

describe('PrivateAPIUsageController dbUsage', () => {
    let controller: PrivateAPIUsageController;
    const mockCreate = jest.fn();
    const businessID = 'fakeBusiness';
    const usageRecord = {
        timeStamp: '2023-02-08T19:24:10Z',
        dimensionId: 'da9611bd-e0f3-4c0d-a754-fda5be730872',
        applicationId: 'e8366954-6f36-47e9-8431-ac95f88b5cc7',
        recordValue: '0.87',
    };

    beforeEach(async () => {
        jest.clearAllMocks();
        s3Mock.reset();
        s3Mock.on(PutObjectCommand).resolves({});
        process.env.DB_MEASUREMENT_BUCKET_NAME = 'enterprise-usage-record-dump-bucket';
        process.env.DB_MEASUREMENT_DLQ_BUCKET_NAME = 'enterprise-usage-record-dlq-bucket';
        mockCreate.mockResolvedValue({ message: 'Measurement created' });

        const module: TestingModule = await Test.createTestingModule({
            controllers: [PrivateAPIUsageController],
        })
            .useMocker((token) => {
                if (token === UsageService) {
                    return { create: mockCreate };
                }
            })
            .compile();

        controller = module.get<PrivateAPIUsageController>(PrivateAPIUsageController);
    });

    it('sends valid records through the usage service with the businessID of the s3Key', async () => {
        const response = await controller.dbUsage({
            message: JSON.stringify(usageRecord),
            s3Key: `${businessID}/2023/02/08/usage-record.json`,
        } as never);

        expect(mockCreate).toHaveBeenCalledWith({ ...usageRecord, businessID });
        expect(response).toEqual({ message: 'Measurement created' });
        expect(s3Mock.commandCalls(PutObjectCommand).length).toEqual(0);
    });

    it('publishes malformed records to the DLQ mirroring the source key', async () => {
        const s3Key = `${businessID}/2023/02/08/usage-record.json`;
        const input = { message: 'i am not json', s3Key };

        await controller.dbUsage(input as never);

        expect(mockCreate).not.toHaveBeenCalled();
        const [putObject] = s3Mock.commandCalls(PutObjectCommand);
        expect(putObject.args[0].input.Bucket).toEqual(process.env.DB_MEASUREMENT_DLQ_BUCKET_NAME);
        expect(putObject.args[0].input.Key).toEqual(`${s3Key}.message.text`);
        const body = JSON.parse(`${putObject.args[0].input.Body}`);
        expect(body.failedInput).toEqual(input);
        expect(body.processingMetadata.businessID).toEqual(businessID);
        expect(body.processingMetadata.error).toBeDefined();
    });

    it('supports absolute source keys when publishing to the DLQ', async () => {
        const s3Key = `s3://${process.env.DB_MEASUREMENT_BUCKET_NAME}/${businessID}/2023/02/08/usage-record.json`;

        await controller.dbUsage({ message: '{"broken":', s3Key } as never);

        const [putObject] = s3Mock.commandCalls(PutObjectCommand);
        expect(putObject.args[0].input.Key).toEqual(`${businessID}/2023/02/08/usage-record.json.message.text`);
    });

    it('publishes records without a source key to the DLQ', async () => {
        await controller.dbUsage({ message: JSON.stringify(usageRecord) } as never);

        expect(mockCreate).not.toHaveBeenCalled();
        expect(s3Mock.commandCalls(PutObjectCommand).length).toEqual(1);
    });
});

import { Test, TestingModule } from '@nestjs/testing';
import { DimensionsService } from '../dimensions/dimensions.service';
import { InfluxService } from '../influx/influx.service';
import { SchedulerService } from '../scheduler/scheduler.service';
import { measurementMode } from './dto/create-measurement-config.dto';
import { DatastoreAccessInformation } from './entities/measurement-config.entity';
import { MeasurementConfigService } from './measurement-config.service';

const mockCreateRole = jest.fn();
const mockPutRolePolicy = jest.fn();
const mockUpdateAssumeRolePolicy = jest.fn();

jest.mock('@aws-sdk/client-iam', () => ({
    IAM: jest.fn().mockImplementation(() => ({
        createRole: mockCreateRole,
        putRolePolicy: mockPutRolePolicy,
        updateAssumeRolePolicy: mockUpdateAssumeRolePolicy,
    })),
}));

describe('MeasurementConfigService datastore based measurements', () => {
    let service: MeasurementConfigService;
    const businessID = 'fakeBusiness';
    const accountId = '623673123435';
    const mockLoadPoints = jest.fn();
    const mockReadMeasurementConfigData = jest.fn();
    let tags: Record<string, string> = {};

    beforeEach(async () => {
        jest.clearAllMocks();
        tags = {};
        process.env.DB_MEASUREMENT_BUCKET_NAME = 'enterprise-usage-record-dump-bucket';
        process.env.DB_MEASUREMENT_DLQ_BUCKET_NAME = 'enterprise-usage-record-dlq-bucket';
        mockCreateRole.mockImplementation(({ RoleName }) =>
            Promise.resolve({ Role: { Arn: `arn:aws:iam::647662420899:role/${RoleName}` } })
        );
        mockPutRolePolicy.mockResolvedValue({});
        mockUpdateAssumeRolePolicy.mockResolvedValue({});

        const module: TestingModule = await Test.createTestingModule({
            providers: [MeasurementConfigService],
            imports: [],
        })
            .useMocker((token) => {
                if (token === InfluxService) {
                    return {
                        loadPoints: mockLoadPoints,
                        getPoint: () => ({
                            tag: (key, value) => {
                                tags[key] = value;
                            },
                            stringField: jest.fn(),
                        }),
                        readMeasurementConfigData: mockReadMeasurementConfigData,
                    };
                }
                if (token === SchedulerService) {
                    return { create: jest.fn() };
                }
                if (token === DimensionsService) {
                    return { transformDtoToEntityInput: jest.fn(), findOneByDimensionId: jest.fn() };
                }
            })
            .compile();

        service = module.get<MeasurementConfigService>(MeasurementConfigService);
    });

    it('provisions and persists the generated access information', async () => {
        const response = await service.create(
            {
                businessID,
                measurementMode: measurementMode.datastoreBased,
                measurementConfiguration: { accountId } as DatastoreAccessInformation,
                measurementName: 'fakeDatastoreMeasurement',
            },
            'fakeSubject'
        );

        const { measurementId } = response;
        const configuration = response.measurementConfiguration as DatastoreAccessInformation;
        expect(configuration.platform).toEqual('s3');
        expect(configuration.accountId).toEqual(accountId);
        expect(configuration.iamRoleArn).toEqual(
            `arn:aws:iam::647662420899:role/datastore-${businessID}-${measurementId}`
        );
        expect(configuration.externalId).toBeDefined();
        expect(configuration.ingestion).toEqual(
            `s3://${process.env.DB_MEASUREMENT_BUCKET_NAME}/${businessID}/`
        );
        expect(configuration.dlq).toEqual(`s3://${process.env.DB_MEASUREMENT_DLQ_BUCKET_NAME}/${businessID}/`);
        expect(configuration.region).toEqual('us-east-1');

        // The generated access information is persisted alongside the measurement
        expect(mockLoadPoints).toHaveBeenCalled();
        expect(tags.platform).toEqual('s3');
        expect(tags.accountId).toEqual(accountId);
        expect(tags.iamRoleArn).toEqual(configuration.iamRoleArn);
        expect(tags.externalId).toEqual(configuration.externalId);
        expect(tags.ingestion).toEqual(configuration.ingestion);
        expect(tags.dlq).toEqual(configuration.dlq);
        expect(tags.region).toEqual('us-east-1');
    });

    it('updates the trust of the provisioned role when the account changes', async () => {
        const measurementId = 'fake-measurement-id';
        const externalId = 'already-generated-external-id';
        const iamRoleArn = `arn:aws:iam::647662420899:role/datastore-${businessID}-${measurementId}`;
        mockReadMeasurementConfigData.mockResolvedValue([
            {
                measurementId,
                businessID,
                measurementName: 'fakeDatastoreMeasurement',
                subject: 'fakeSubject',
                _value: measurementMode.datastoreBased,
                platform: 's3',
                accountId,
                iamRoleArn,
                externalId,
                ingestion: `s3://${process.env.DB_MEASUREMENT_BUCKET_NAME}/${businessID}/`,
                dlq: `s3://${process.env.DB_MEASUREMENT_DLQ_BUCKET_NAME}/${businessID}/`,
                region: 'us-east-1',
            },
        ]);

        const updatedAccountId = '999999999999';
        const response = await service.update(
            {
                measurementId,
                businessID,
                measurementName: undefined,
                measurementMode: measurementMode.datastoreBased,
                measurementConfiguration: { accountId: updatedAccountId },
            },
            'fakeSubject'
        );

        const [[updateTrustInput]] = mockUpdateAssumeRolePolicy.mock.calls;
        expect(updateTrustInput.RoleName).toEqual(`datastore-${businessID}-${measurementId}`);
        const trust = JSON.parse(updateTrustInput.PolicyDocument);
        expect(trust.Statement[0].Principal.AWS).toEqual(`arn:aws:iam::${updatedAccountId}:root`);
        expect(trust.Statement[0].Condition.StringEquals['sts:ExternalId']).toEqual(externalId);

        const configuration = response.measurementConfiguration as DatastoreAccessInformation;
        expect(configuration.accountId).toEqual(updatedAccountId);
        expect(configuration.externalId).toEqual(externalId);
        expect(configuration.iamRoleArn).toEqual(iamRoleArn);
        expect(tags.accountId).toEqual(updatedAccountId);
        expect(tags.externalId).toEqual(externalId);
        expect(tags.iamRoleArn).toEqual(iamRoleArn);
    });
});

